from lib import *
S = SS('c82')
steps = [
    step("Dockerfile:alpine 之后依次 RUN 生成 10 MiB 的 a.bin、5 MiB 的 b.bin、再写一遍 a.bin(不同内容)、rm b.bin、chmod 600 a.bin(前面还有一条 echo 盐)。docker save 出来共 7 层,逐层统计:层 0(alpine 根文件系统)tar 9.1 MB;层 2 加入 a.bin(10.5MB);层 3 加入 b.bin(5.2MB);层 4 又是一份 10.5MB 的 a.bin;层 5 几乎是空的,只有一个 whiteout(data/.wh.b.bin);层 6 是 chmod,但里面又有一份完整的 10.5MB 的 a.bin——只改权限也重写了整个文件。", t=tl(S(1)), done=lidx(S(1), '层 2', '层 3', '层 4'), mark=lidx(S(1), '层 5', '层 6'), b=bars([['层 2 (MB)', 10.5, '10.5'], ['层 3 (MB)', 5.2, '5.2'], ['层 4 (MB)', 10.5, '10.5'], ['层 5 (MB)', 0, '0'], ['层 6 (MB)', 10.5, '10.5']], 10.5, done=[0, 1, 2], mark=[3, 4]), kv=KV([['层 4', '再写 a.bin → 又一份 10.5MB'], ['层 5', 'rm b.bin → 只有 whiteout'], ['层 6', 'chmod → 整个文件重写 10.5MB']], ['层 6'])),
    step("按层顺序跟踪每个路径:data/a.bin 层 2 里的 10.5 MB 在层 4 被覆盖;data/b.bin 层 3 里的 5.2 MB 在层 5 被删除;data/a.bin 层 4 里的 10.5 MB 在层 6 被覆盖。所有层里文件字节总和 45.5 MB,被后面层覆盖或删除的(浪费)共 26.2 MB,有效 19.3 MB,效率 = 有效 ÷ 总和 = 42.4%。容器里实际只看得到一个文件:-rw------- 10485760 a.bin。", t=tl(S(2)), done=lidx(S(2), '所有层里的文件字节总和', '容器里实际可见'), mark=lidx(S(2), '被覆盖', '被删除'), b=bars([['有效 (MB)', 19.3, '19.3'], ['浪费 (MB)', 26.2, '26.2']], 45.5, done=[0], mark=[1]), kv=KV([['文件字节总和', '45.5 MB'], ['浪费(被覆盖或删除)', '26.2 MB'], ['效率', '42.4%']], ['浪费(被覆盖或删除)'])),
    step("把这些操作合并成一条 RUN(生成 a.bin 后 chmod 600)得到的镜像,最终容器里看到的文件相同(-rw------- 10485760 a.bin),但镜像 Size 从 87.0 MB(7 层)降到 34.6 MB。", t=tl(S(3)), done=lidx(S(3), '镜像 Size'), b=bars([['浪费版 (MB)', 87.0, '87.0'], ['合并版 (MB)', 34.6, '34.6']], 87, done=[1], mark=[0]), kv=KV([['浪费版', '87.0 MB,7 层'], ['合并成一条 RUN', '34.6 MB'], ['容器里的文件', '完全相同']], ['合并成一条 RUN'])),
]
A = mkartc('c82', 82, 'Docker,镜像分析,浪费空间,dive,镜像层,真实验证,动画演示',
    '自己写 Python 分析 docker save 出来的镜像层(类似 dive):故意构造覆盖文件、删除文件、只改权限的 Dockerfile,7 层里文件字节总和 45.5 MB,被后面层覆盖或删除的浪费 26.2 MB(效率 42.4%);chmod 也会重写整个 10.5MB 的文件;合并成一条 RUN 后镜像从 87.0 MB 降到 34.6 MB,容器里的文件完全一样。',
    '镜像里哪些字节是白占的?dive 之类的工具是怎么算「浪费空间」的?这篇不装 dive,自己用 Python 读 docker save 的每一层,按路径跟踪文件被覆盖和删除的过程,算出浪费量和效率。',
    [('26.2 MB', '被后面的层覆盖或删除的文件字节(总和 45.5 MB 里)'), ('42.4%', '镜像的空间效率 = 有效字节 ÷ 所有层的文件字节总和'), ('87.0 → 34.6 MB', '把覆盖、删除和 chmod 合并成一条 RUN 后的镜像体积')],
    [('逐层统计', '<p>读 <code>docker save</code> 的每一层 tar(c14 的做法),列出每层加入的大文件和 whiteout。只改权限的 <code>chmod</code> 也会在新层里放一份完整的文件(c20 里同样看到整个文件被复制)。</p>'),
     ('浪费怎么算', '<p>按路径顺序跟踪:同一路径在后面的层里再次出现,前一个版本就被覆盖;出现 whiteout,则被删除。被覆盖或删除版本的大小之和就是浪费。这是我自己的简化算法(只统计普通文件的大小,没有处理硬链接、目录权限等),dive 的实际算法和输出我没有对照。</p>'),
     ('合并 RUN', '<p>把生成、覆盖、删除、改权限放进同一条 RUN,最终的层里只有最后的状态,镜像体积从 87.0 MB 降到 34.6 MB(其中 alpine 基础层 13.6 MB 加上 10 MiB 文件的压缩与解包两份,见 c18)。</p>')],
    steps,
    [ENV_C + '。分析脚本是我自己写的(tarfile 读取 docker save 的 OCI 布局,逐层统计);没有安装或运行 dive;文件用 /dev/urandom 生成;镜像体积取 docker image inspect 的 Size;实验后已删除镜像',
     '没有验证:dive 本身的输出与算法、硬链接和稀疏文件的统计、目录与权限变化的统计、压缩后传输体积的浪费、同一路径被不同类型(文件改成目录)替换的情形'],
    '镜像浪费空间')
